function interviewVoiceReset(){interviewVoiceState.requestId++;interviewVoiceStopSpeech(true);interviewVoiceClearTimer();const recorder=interviewVoiceState.recorder;interviewVoiceAbortRecorder(recorder);interviewVoiceState.chunks=[];interviewVoiceReleaseUrl();interviewVoiceState.status='ready';interviewVoiceState.elapsed=0;interviewVoiceState.startedAt=0;interviewVoiceState.mime='';interviewVoiceState.error='';interviewVoiceState.transcript='';interviewVoiceState.transcriptSource='';interviewVoiceState.transcriptConfidence=null;interviewVoiceState.asrMode='unavailable';interviewVoiceState.feedback=null;interviewVoiceState.analysisMode='';interviewVoiceState.analysisError='';interviewVoiceState.fixture=false;interviewVoiceState.browserSpeechMode='unsupported';interviewVoiceState.browserSpeechProvider='unknown';interviewVoiceState.browserSpeechProviderCalled='unknown';interviewVoiceState.browserSpeechOptIn=true;interviewVoiceState.browserSpeechDecision='enabled';interviewVoiceState.speechConsentPrompt=false;interviewVoiceState.transcriptConfirmedAt='';interviewVoiceState.browserSpeechFinal='';interviewVoiceState.browserSpeechInterim='';interviewVoiceState.browserSpeechError='';interviewVoiceState.browserSpeechDone=true;}
function interviewVoiceLeave(){interviewVoiceReset();}
function interviewVoiceStart(){const busy=['requesting','recording','paused','stopping'];if(busy.includes(interviewVoiceState.status))return;const media=typeof navigator!=='undefined'?navigator.mediaDevices:null;if(!media?.getUserMedia||typeof MediaRecorder==='undefined'){interviewVoiceState.status='unsupported';interviewVoiceState.error='当前浏览器不支持音频录制。你仍可返回题目使用文字回答或打开独立演示。';render();focusTitle();return;}interviewVoiceReleaseUrl();interviewVoiceState.chunks=[];interviewVoiceState.blob=null;interviewVoiceState.mime='';interviewVoiceState.error='';const requestId=++interviewVoiceState.requestId;interviewVoiceState.status='requesting';interviewVoiceState.elapsed=0;interviewVoiceState.startedAt=0;render();focusTitle();let permission;try{permission=media.getUserMedia({audio:true});}catch(error){interviewVoiceState.status=error?.name==='NotAllowedError'||error?.name==='PermissionDeniedError'?'permission_denied':'error';interviewVoiceState.error=interviewVoiceState.status==='permission_denied'?'麦克风权限被拒绝；未保存或上传任何音频，请改用文字回答或重新允许权限。':'无法访问麦克风（'+(error?.name||'未知原因')+'）；未保存或上传任何音频。';render();focusTitle();return;}Promise.resolve(permission).then(stream=>{if(requestId!==interviewVoiceState.requestId||interviewVoiceState.status!=='requesting'){stream.getTracks?.().forEach(track=>{try{track.stop();}catch{}});return;}interviewVoiceState.stream=stream;return interviewVoiceResolveDevice(stream,media).then(deviceCheck=>{if(requestId!==interviewVoiceState.requestId){stream.getTracks?.().forEach(track=>{try{track.stop();}catch{}});return;}if(!deviceCheck.allowed){interviewVoiceDeviceDenied(deviceCheck.reason);return;}const candidates=['audio/webm;codecs=opus','audio/webm','audio/mp4'];const mime=typeof MediaRecorder.isTypeSupported==='function'?candidates.find(x=>MediaRecorder.isTypeSupported(x))||'':'';let recorder;try{recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);}catch{interviewVoiceStopTracks();interviewVoiceState.recorder=null;interviewVoiceState.status='unsupported';interviewVoiceState.error='浏览器无法创建录音格式；未保存或上传任何音频。';render();focusTitle();return;}interviewVoiceState.recorder=recorder;interviewVoiceState.mime=mime||recorder.mimeType||'audio/webm';interviewVoiceState.startedAt=Date.now();interviewVoiceState.elapsed=0;interviewVoiceState.status='recording';recorder.ondataavailable=e=>{if(requestId!==interviewVoiceState.requestId||interviewVoiceState.recorder!==recorder)return;if(e.data&&e.data.size)interviewVoiceState.chunks.push(e.data);};recorder.onerror=()=>{if(requestId!==interviewVoiceState.requestId||interviewVoiceState.recorder!==recorder)return;interviewVoiceClearTimer();interviewVoiceDetachRecorder(recorder);interviewVoiceStopSpeech(true);interviewVoiceStopTracks();interviewVoiceState.recorder=null;interviewVoiceState.status='error';interviewVoiceState.error='录音过程中发生错误；音频仍只在本页内存中。';render();focusTitle();};recorder.onstop=()=>{if(requestId!==interviewVoiceState.requestId||interviewVoiceState.recorder!==recorder)return;interviewVoiceClearTimer();interviewVoiceStopTracks();const size=interviewVoiceState.chunks.reduce((n,c)=>n+c.size,0);interviewVoiceState.recorder=null;if(!size){interviewVoiceState.status='empty';interviewVoiceState.error='没有捕获到可播放音频，请检查麦克风权限或输入后重试。';render();focusTitle();return;}interviewVoiceState.blob=new Blob(interviewVoiceState.chunks,{type:interviewVoiceState.mime||'audio/webm'});interviewVoiceState.url=typeof URL!=='undefined'&&URL.createObjectURL?URL.createObjectURL(interviewVoiceState.blob):'';interviewVoiceState.status='captured';render();focusTitle();};try{recorder.start();}catch{interviewVoiceClearTimer();interviewVoiceAbortRecorder(recorder);interviewVoiceState.status='error';interviewVoiceState.error='浏览器无法开始录音；请返回后使用文字回答。';render();focusTitle();return;}interviewVoiceState.timer=setInterval(()=>{if(requestId!==interviewVoiceState.requestId||interviewVoiceState.status!=='recording')return;interviewVoiceState.elapsed=Math.max(0,Math.round((Date.now()-interviewVoiceState.startedAt)/1000));const timer=document.getElementById('interview-voice-time');if(timer)timer.textContent=interviewFormatDuration(interviewVoiceState.elapsed);},500);interviewVoiceStartSpeech(requestId);render();focusTitle();});}).catch(error=>{if(requestId!==interviewVoiceState.requestId)return;interviewVoiceStopTracks();interviewVoiceState.status=error?.name==='NotAllowedError'||error?.name==='PermissionDeniedError'?'permission_denied':'error';interviewVoiceState.error=interviewVoiceState.status==='permission_denied'?'麦克风权限被拒绝；未保存或上传任何音频，请改用文字回答或重新允许权限。':'无法访问麦克风（'+(error?.name||'未知原因')+'）；未保存或上传任何音频。';render();focusTitle();});}
function interviewVoicePause(){const recorder=interviewVoiceState.recorder;if(interviewVoiceState.status!=='recording'||recorder?.state!=='recording')return;try{recorder.pause();interviewVoiceState.elapsed=Math.max(0,Math.round((Date.now()-interviewVoiceState.startedAt)/1000));interviewVoiceState.status='paused';}catch{interviewVoiceClearTimer();interviewVoiceStopSpeech(true);interviewVoiceAbortRecorder(recorder);interviewVoiceState.status='error';interviewVoiceState.error='浏览器无法暂停录音；请停止录音或返回文字回答。';}render();focusTitle();}
function interviewVoiceResume(){const recorder=interviewVoiceState.recorder;if(interviewVoiceState.status!=='paused'||recorder?.state!=='paused')return;try{recorder.resume();interviewVoiceState.startedAt=Date.now()-interviewVoiceState.elapsed*1000;interviewVoiceState.status='recording';}catch{interviewVoiceClearTimer();interviewVoiceStopSpeech(true);interviewVoiceAbortRecorder(recorder);interviewVoiceState.status='error';interviewVoiceState.error='浏览器无法继续录音；请重新录音或返回文字回答。';}render();focusTitle();}
function interviewVoiceStop(){const recorder=interviewVoiceState.recorder;if(!recorder||!['recording','paused'].includes(recorder.state)||!['recording','paused'].includes(interviewVoiceState.status))return;interviewVoiceState.status='stopping';interviewVoiceStopSpeech(false);try{recorder.stop();}catch{interviewVoiceClearTimer();interviewVoiceStopSpeech(true);interviewVoiceAbortRecorder(recorder);interviewVoiceState.status='error';interviewVoiceState.error='浏览器无法停止录音；请重试或返回文字回答。';}render();focusTitle();}
function interviewFormatDuration(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function interviewVoiceList(items,empty){const list=Array.isArray(items)?items:[];return list.length?'<ul class="interview-voice-list">'+list.map(item=>'<li>'+escapeHTML(typeof item==='string'?item:(item.text||item.action||''))+'</li>').join('')+'</ul>':'<p class="muted">'+escapeHTML(empty||'暂无')+'</p>';}
function interviewVoiceBrowserSpeechTouched(v){return Boolean(v?.browserSpeechOptIn||v?.transcriptSource==='browser_speech'||['starting','listening','ended','network_error','permission_denied','error'].includes(v?.browserSpeechMode));}
function interviewVoiceSpeechPrivacy(v){const used=interviewVoiceBrowserSpeechTouched(v);return used?'浏览器 SpeechRecognition 已处理语音；是否联网、供应商和保留期限由浏览器/系统决定，当前无法确认。它不是本地 ASR；Rolecraft 不把音频上传到自己的服务。':'当前未使用浏览器 SpeechRecognition；Rolecraft 不上传音频，录音仅保留在本页内存。';}
function interviewVoiceSpeechLiveHTML(v){const mode=v?.browserSpeechMode||'unsupported';if(mode==='opted_out')return '<p class="interview-voice-speech-note">未启用浏览器语音识别；录音仍可试听，停止后可以手动输入或载入测试转写。</p>';if(mode==='unsupported')return '<p class="interview-voice-speech-note">浏览器 SpeechRecognition 不可用；不会因此上传音频，可停止后手动输入或载入测试转写。</p>';const live=interviewVoiceSpeechLiveText();const error=v?.browserSpeechError||'';return '<section class="interview-voice-speech-live" aria-live="polite"><div><strong>浏览器语音识别候选 · '+escapeHTML(mode)+'</strong><span class="interview-voice-unknown-badge">网络/供应商/保留：未知</span></div><p class="interview-voice-speech-disclosure">'+escapeHTML(interviewVoiceSpeechPrivacy(v))+'</p><p class="interview-voice-speech-final">'+escapeHTML(live||'等待浏览器返回识别文字…')+'</p>'+(error?'<p class="interview-voice-error" role="alert">'+escapeHTML(error)+'</p>':'')+'</section>';}
function interviewVoiceFeedbackHTML(f){if(!f)return '';const a=f.answerAnalysis||{},d=f.delivery||{},g=f.contentGrounding||{},p=f.provenance||{};const modelProvider=p.providerCalled===false?'false':(p.providerCalled===true?'true':'unknown');const browserNote='';return '<section class="interview-voice-feedback" aria-live="polite"><div class="interview-voice-feedback-head"><div><span class="tag">本地规则反馈 · '+escapeHTML(f.status||'completed')+'</span><h2>反馈与下一次重答</h2></div><span class="interview-voice-local-badge">分析 providerCalled='+modelProvider+'</span></div>'+browserNote+'<p class="interview-voice-summary">'+escapeHTML(a.summary||'已完成本地分析。')+'</p><div class="interview-voice-feedback-grid"><article><h3>回答中的可观察亮点</h3>'+interviewVoiceList(a.strengths,'暂未识别到可核对亮点。')+'</article><article><h3>需要补齐的证据</h3>'+interviewVoiceList(a.gaps,'当前规则未发现明显缺项；仍需人工核对技术事实。')+'</article><article><h3>下一次动作</h3>'+interviewVoiceList(a.coaching,'请结合题目量规自行复盘。')+'</article><article><h3>可继续追问</h3>'+interviewVoiceList(a.followUpQuestions,'暂无追问。')+'</article></div><div class="interview-voice-evidence"><h3>来源与测量边界</h3><p>题目来源：'+escapeHTML(f.questionSource||((g.sections||[]).map(x=>x.title).join('、')||'当前精选题'))+' · 教材绑定状态：'+escapeHTML(g.bindingStatus||'none')+'</p><p>表达测量：'+escapeHTML(d.measurement||'unavailable')+' · 字数/字符数：'+escapeHTML(String(d.wordCount??'不可用'))+' · 填充词：'+escapeHTML((d.fillerWords||[]).map(x=>typeof x==='string'?x:(x.word+(x.count?' ×'+x.count:''))).join('、')||'未发现')+'</p><p>ASR：'+escapeHTML(p.asrMode||'unavailable')+' · 分析：'+escapeHTML(p.analysisMode||'local_rules')+' · 模型：'+escapeHTML(p.model||'interview-local-rules-v1')+'</p><p class="muted">'+escapeHTML((f.uncertainty||[]).map(x=>x.reason).join('；')||'本地规则仅依据转写文本，不推断口音、情绪、自信度或录用结果。')+'</p></div><div class="interview-voice-retry"><strong>重答提示</strong><p>'+escapeHTML(a.retryPrompt||'请根据缺口重新回答，并给出一个可验证例子。')+'</p><button class="primary" data-interview-action="voice-rerecord-feedback">重新录音回答</button><button class="outline" data-interview-action="voice-edit-transcript">修改转写后重分析</button></div></section>';}
function interviewVoiceTranscriptHTML(v){if(!['captured','transcribing','transcript_ready','transcription_unavailable','analyzing','feedback'].includes(v.status))return '';const editable=['transcript_ready','transcription_unavailable'].includes(v.status);const text=escapeHTML(v.transcript||'');const label=v.status==='transcribing'?'正在转写…':v.status==='analyzing'?'正在分析…':v.status==='feedback'?'已确认的转写':'转写校对';let actions='';if(v.status==='transcript_ready'||v.status==='transcription_unavailable')actions='<button class="primary" data-interview-action="voice-analyze">确认并分析</button>';if(v.status==='feedback')actions='<button class="outline" data-interview-action="voice-edit-transcript">修改转写</button>';const suggestions=Array.isArray(v.correctionSuggestions)?v.correctionSuggestions:[];const correctionHTML=editable?'<div class="interview-voice-corrections"><h3>术语纠错</h3>'+(suggestions.length?'<div class="interview-correction-list">'+suggestions.map(x=>'<div class="interview-correction-item"><span><strong>'+escapeHTML(x.from)+'</strong> → <strong>'+escapeHTML(x.to)+'</strong></span><small>'+escapeHTML(x.reason)+'</small><button class="text-link" data-interview-action="voice-apply-correction" data-correction-id="'+escapeHTML(x.id)+'">采纳</button></div>').join('')+'</div><button class="outline" data-interview-action="voice-apply-all-corrections">一键采纳</button>':'<p class="muted">暂无纠错建议</p>')+'</div>':'';const showError=v.status==='transcription_unavailable'&&v.error;return '<section class="interview-voice-transcript"><div class="interview-voice-section-head"><h2>'+label+'</h2></div><textarea id="interview-voice-transcript" '+(editable?'':'readonly')+' aria-label="回答转写" placeholder="请输入或粘贴回答">'+text+'</textarea>'+correctionHTML+(showError?'<p class="interview-voice-error" role="alert">'+escapeHTML(v.error)+'</p>':'')+'<div class="interview-voice-actions">'+actions+'</div></section>';}
function interviewVoiceConsentDialog(v){if(!v.speechConsentPrompt)return '';return '<section id="interview-voice-speech-consent-dialog" class="interview-voice-consent-prompt" role="dialog" aria-modal="true" aria-labelledby="interview-voice-consent-title"><h2 id="interview-voice-consent-title">启用浏览器语音识别？</h2><p>当前浏览器支持 SpeechRecognition。启用后可以实时显示文字候选，但浏览器/系统可能把语音交给外部服务；是否联网、供应商和保留期限未知。</p><p>Rolecraft 不把音频上传到自己的服务；识别文字仍需你校对后才进入本地规则分析。</p><div class="interview-voice-consent-actions"><button class="primary" data-interview-action="voice-consent-enable">启用浏览器语音识别并开始</button><button class="outline" data-interview-action="voice-consent-record-only">只录音，稍后手动转写</button><button class="text-link" data-interview-action="voice-consent-cancel">取消</button></div></section>';}
function interviewVoicePage(){const q=interviewVoiceQuestion(),v=interviewVoiceState;const statusText={ready:'准备录音',requesting:'请求麦克风',recording:'正在录音',paused:'已暂停',stopping:'正在结束录音',captured:'录音已完成',transcribing:'正在转写',transcript_ready:'等待确认转写',transcription_unavailable:'转写不可用',analyzing:'正在分析',feedback:'已生成反馈',permission_denied:'权限未授予',device_denied:'麦克风不可用',unsupported:'浏览器不支持',empty:'没有音频',error:'录音失败'}[v.status]||'准备录音';let controls='';if(v.status==='ready'||['permission_denied','device_denied','unsupported','empty','error'].includes(v.status))controls='<button class="primary" data-interview-action="voice-start">开始录音</button>';if(v.status==='requesting')controls='<button class="outline" data-interview-action="voice-cancel">取消</button>';if(v.status==='recording')controls='<button class="primary" data-interview-action="voice-pause">暂停</button><button class="outline" data-interview-action="voice-stop">停止</button>';if(v.status==='paused')controls='<button class="primary" data-interview-action="voice-resume">继续录音</button><button class="outline" data-interview-action="voice-stop">停止</button><button class="text-link" data-interview-action="voice-delete">放弃</button>';if(v.status==='captured')controls='<button class="primary" data-interview-action="voice-transcribe">使用本地转写</button><button class="text-link" data-interview-action="voice-rerecord">重新录音</button>';if(['transcript_ready','transcription_unavailable'].includes(v.status))controls='<button class="text-link" data-interview-action="voice-rerecord">重新录音</button>';if(v.status==='feedback')controls='<button class="outline" data-interview-action="voice-rerecord-feedback">重新录音回答</button>';const audio=v.status!=='ready'&&v.status!=='recording'&&v.status!=='paused'&&v.url?'<audio controls preload="metadata" src="'+escapeHTML(v.url)+'"></audio>':'';const hint=v.status==='requesting'?'请允许麦克风权限':v.status==='recording'?'说完后点击停止':v.status==='captured'?'录音完成，可转写或重录':v.status==='transcription_unavailable'?'请手动输入转写':v.status==='transcript_ready'?'请校对文字后确认':v.status==='feedback'?'可修改转写或重新录音':'点击开始录音';const browserSpeechError=v.browserSpeechError||'';const speechSupported=typeof interviewVoiceSpeechCtor()==='function';const speechSettings=['ready','permission_denied','device_denied','unsupported','empty','error'].includes(v.status)?'<details class="interview-voice-advanced"><summary>识别设置</summary><label class="interview-voice-speech-consent"><input type="checkbox" data-interview-speech-consent '+(v.browserSpeechOptIn?'checked':'')+(speechSupported?'':' disabled')+'> 使用浏览器语音识别</label></details>':'';const extraTranscription=v.status==='captured'?'<details class="interview-voice-advanced"><summary>其他转写方式</summary><div class="interview-voice-actions"><button class="outline" data-interview-action="voice-fixture">载入测试转写</button></div></details>':'';const browserError=browserSpeechError&&!['recording','paused'].includes(v.status)?'<p class="interview-voice-error" role="alert">'+escapeHTML(browserSpeechError)+'</p>':'';return '<div class="interview-prep interview-screen interview-voice-page">'+interviewVoiceConsentDialog(v)+interviewPageHead('精选题 · 语音练习',q.id+' · 说出你的回答','录音后校对文字','')+'<button class="outline interview-back" data-interview-action="voice-back">← 返回精选题</button><section class="interview-voice-card"><div class="interview-voice-question"><span class="tag">'+escapeHTML(q.type)+' · '+escapeHTML(q.round)+'</span><h2>'+escapeHTML(q.title)+'</h2></div><div class="interview-voice-status" aria-live="polite"><span class="interview-voice-dot '+escapeHTML(v.status)+'" aria-hidden="true"></span><strong>'+statusText+'</strong><span id="interview-voice-time">'+interviewFormatDuration(v.elapsed)+'</span></div><p class="interview-voice-hint">'+hint+'</p>'+speechSettings+'<div class="interview-voice-actions">'+controls+'</div>'+audio+browserError+(v.error&& !['transcript_ready','feedback','transcription_unavailable'].includes(v.status)?'<div class="interview-voice-error" role="alert">'+escapeHTML(v.error)+'</div>':'')+extraTranscription+'</section>'+interviewVoiceTranscriptHTML(v)+(v.status==='feedback'?interviewVoiceFeedbackHTML(v.feedback):'')+'</div>';}
/* 面试准备语音：本地优先；适配器缺失时显式不可用并回退到用户确认转写。 */
